// Local appearance candidates for cosmetic retouch; no disease labels or probabilities.
const clamp=x=>Math.max(0,Math.min(1,x));
function mean(values,w,h,r){const stride=w+1,ii=new Float64Array(stride*(h+1)),out=new Float32Array(values.length);for(let y=0;y<h;y++){let row=0;for(let x=0;x<w;x++){row+=values[y*w+x];ii[(y+1)*stride+x+1]=ii[y*stride+x+1]+row;}}for(let y=0;y<h;y++)for(let x=0;x<w;x++){const l=Math.max(0,x-r),rr=Math.min(w,x+r+1),t=Math.max(0,y-r),b=Math.min(h,y+r+1);out[y*w+x]=(ii[b*stride+rr]-ii[t*stride+rr]-ii[b*stride+l]+ii[t*stride+l])/((rr-l)*(b-t));}return out;}
function components(mask,w,h,maximum,elongated){const seen=new Uint8Array(mask.length),out=new Float32Array(mask.length),q=new Int32Array(mask.length),regions=[];let count=0,pixels=0;for(let start=0;start<mask.length;start++){if(seen[start]||mask[start]<.12)continue;let head=0,tail=1,l=w,r=0,t=h,b=0;q[0]=start;seen[start]=1;while(head<tail){const i=q[head++],x=i%w,y=Math.floor(i/w);l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);for(const n of[x?i-1:-1,x+1<w?i+1:-1,y?i-w:-1,y+1<h?i+w:-1])if(n>=0&&!seen[n]&&mask[n]>=.12){seen[n]=1;q[tail++]=n;}}const rw=r-l+1,rh=b-t+1;if(tail<Math.max(2,Math.round(w*h/300000))||tail>maximum||elongated&&Math.max(rw,rh)/Math.min(rw,rh)<2)continue;for(let k=0;k<tail;k++)out[q[k]]=mask[q[k]];count++;pixels+=tail;if(regions.length<1000)regions.push({x:l,y:t,width:rw,height:rh,pixels:tail});}return{mask:out,regions,count,pixels};}
export function analyzeSkinSurface({data,width:w,height:h,skin,sensitivity=1}){
 const n=w*h;if(data.length!==n*4||skin.length!==n||n>2097152||n<100||!Number.isFinite(sensitivity)||sensitivity<.2||sensitivity>1.8)throw Error('Dữ liệu phân tích da không hợp lệ.');
 const light=new Float32Array(n),red=new Float32Array(n),sat=new Float32Array(n);let total=0,dark=0,bright=0,edge=0;
 for(let i=0;i<n;i++){const r=data[i*4],g=data[i*4+1],b=data[i*4+2];light[i]=.2126*r+.7152*g+.0722*b;red[i]=r-(g+b)/2;sat[i]=Math.max(r,g,b)-Math.min(r,g,b);if(skin[i]>.65&&data[i*4+3]>200){total++;if(light[i]<25)dark++;if(light[i]>245)bright++;if(i%w)edge+=Math.abs(light[i]-light[i-1]);}}
 const issues=[];if(total<Math.max(100,n*.002))issues.push('Không đủ vùng da rõ để phân tích.');if(total&&dark/total>.45)issues.push('Vùng da quá tối.');if(total&&bright/total>.45)issues.push('Vùng da bị cháy sáng.');if(total&&edge/total<.5)issues.push('Thiếu chi tiết để tách dấu vết.');if(issues.length)return{status:'insufficient',issues,skinPixels:total,maps:{},method:'local-residual-v1'};
 const radius=Math.max(3,Math.round(Math.min(w,h)*.018)),base=mean(light,w,h,radius),redBase=mean(red,w,h,radius*2),satBase=mean(sat,w,h,radius),c=Object.fromEntries(['dark','red','bright','creases'].map(k=>[k,new Float32Array(n)])),threshold=1.65-sensitivity*.55;
 for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){const i=y*w+x;if(skin[i]<.65||data[i*4+3]<200||light[i]<25||light[i]>245||[i-1,i+1,i-w,i+w].some(j=>skin[j]<.55))continue;const low=base[i]-light[i],high=light[i]-base[i],r=red[i]-redBase[i];c.dark[i]=clamp((low-7*threshold)/16);c.red[i]=red[i]>2?clamp((r-6*threshold)/18):0;c.bright[i]=sat[i]<Math.max(12,satBase[i]*.8)?clamp((high-8*threshold)/18):0;c.creases[i]=clamp((low-5*threshold)/12);}
 const maps={};for(const[k,mask]of Object.entries(c))maps[k]=components(mask,w,h,Math.max(20,total*.06),k==='creases');return{status:'ready',issues:[],skinPixels:total,maps,method:'local-residual-v1'};
}
